#!/usr/bin/env bash
# Generates .env (random secrets) and a self-signed TLS certificate.
# Existing files are never overwritten.
set -Eeuo pipefail
cd "$(dirname "$0")"

rand() { openssl rand -hex "${1:-16}"; }

if [ -f .env ]; then
    echo ".env already exists, keeping it"
else
    HTTPS_PORT=8443
    cat > .env <<EOF
# Generated by setup.sh. Do not commit.

# Published ports
HTTP_PORT=8080
HTTPS_PORT=${HTTPS_PORT}
STATS_PORT=8404

# Number of WordPress replicas (can also be changed with --scale)
WORDPRESS_REPLICAS=2

# Public URL. Must match how you reach HAProxy from your browser.
WORDPRESS_URL=https://localhost:${HTTPS_PORT}
WORDPRESS_TITLE="WordPress HA"
WORDPRESS_ADMIN_USER=admin
WORDPRESS_ADMIN_PASSWORD=$(rand 12)
WORDPRESS_ADMIN_EMAIL=admin@example.com

# Database
WORDPRESS_DB_NAME=wordpress
WORDPRESS_DB_USER=wordpress
WORDPRESS_DB_PASSWORD=$(rand)
MARIADB_ROOT_PASSWORD=$(rand)
GALERA_SST_PASSWORD=$(rand)
PROXYSQL_MONITOR_PASSWORD=$(rand)
PROXYSQL_ADMIN_PASSWORD=$(rand)

# Redis
REDIS_PASSWORD=$(rand)

# HAProxy stats page (http://127.0.0.1:8404/stats)
STATS_USER=admin
STATS_PASSWORD=$(rand 12)

# WordPress keys and salts (identical on every node)
WORDPRESS_AUTH_KEY=$(rand 32)
WORDPRESS_SECURE_AUTH_KEY=$(rand 32)
WORDPRESS_LOGGED_IN_KEY=$(rand 32)
WORDPRESS_NONCE_KEY=$(rand 32)
WORDPRESS_AUTH_SALT=$(rand 32)
WORDPRESS_SECURE_AUTH_SALT=$(rand 32)
WORDPRESS_LOGGED_IN_SALT=$(rand 32)
WORDPRESS_NONCE_SALT=$(rand 32)
EOF
    chmod 600 .env
    echo "wrote .env"
fi

mkdir -p certs
if [ -f certs/site.pem ]; then
    echo "certs/site.pem already exists, keeping it"
else
    openssl req -x509 -newkey rsa:2048 -nodes -sha256 -days 365 \
        -subj "/CN=localhost" \
        -addext "subjectAltName=DNS:localhost,IP:127.0.0.1" \
        -keyout certs/site.key -out certs/site.crt 2>/dev/null
    cat certs/site.crt certs/site.key > certs/site.pem
    # The haproxy user inside the container must be able to read it.
    chmod 644 certs/site.pem certs/site.crt
    chmod 600 certs/site.key
    echo "wrote certs/site.pem (self-signed, valid 365 days)"
fi
